            <p class="error-text" id="${id}-error" hidden></p>
          </div>
        `;
      }

      function App() {
        return `
          <section class="support-card" aria-labelledby="support-title">
            <header class="support-card__header">
              <p class="eyebrow">Support</p>
              <h1 id="support-title">Contact our team</h1>
            </header>
            <div class="support-card__body">
              <p class="support-copy">
