<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1220;
        --panel: #111a2e;
        --panel-2: #16213a;
        --border: #26324d;
        --text: #e8eefc;
        --muted: #9aa8c7;
        --accent: #6ea8fe;
        --accent-2: #8b5cf6;
        --danger: #ff7a7a;
        --shadow: 0 24px 60px rgba(0, 0, 0, 0.38);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
          sans-serif;
        background:
          radial-gradient(circle at top, rgba(110, 168, 254, 0.16), transparent 34%),
          linear-gradient(180deg, #060a14 0%, var(--bg) 100%);
        color: var(--text);
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 24px;
      }

      .support-card {
        width: min(100%, 720px);
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02));
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: 24px;
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .support-card__header {
        padding: 32px 32px 8px;
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.05), transparent);
      }

      .eyebrow {
        margin: 0 0 10px;
        font-size: 0.82rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--accent);
      }

      h1 {
        margin: 0;
        font-size: clamp(1.8rem, 2.8vw, 2.5rem);
        line-height: 1.1;
      }

      .support-card__body {
        padding: 24px 32px 32px;
      }

      .support-copy {
        margin: 0 0 24px;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 600;
        font-size: 0.95rem;
      }

      .required-mark {
        color: var(--accent);
      }

      input {
        width: 100%;
        border: 1px solid var(--border);
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02));
        color: var(--text);
        border-radius: 14px;
        padding: 14px 16px;
        font-size: 1rem;
        transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
      }

      input::placeholder {
        color: #6f7d9d;
      }

      input:focus {
        outline: none;
        border-color: rgba(110, 168, 254, 0.9);
        box-shadow: 0 0 0 4px rgba(110, 168, 254, 0.15);
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.88rem;
        line-height: 1.5;
      }

      .error-text {
        margin: 0;
        color: var(--danger);
        font-size: 0.88rem;
        line-height: 1.5;
        min-height: 1.2em;
      }

      .error-text[hidden] {
        display: none;
      }

      .form-actions {
        display: flex;
        justify-content: flex-end;
        padding-top: 6px;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        font: inherit;
        font-weight: 700;
        color: white;
        cursor: pointer;
        background: linear-gradient(135deg, var(--accent), var(--accent-2));
        box-shadow: 0 12px 30px rgba(110, 168, 254, 0.22);
        transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 16px 34px rgba(110, 168, 254, 0.28);
      }

      button:focus {
        outline: none;
        box-shadow: 0 0 0 4px rgba(110, 168, 254, 0.18), 0 16px 34px rgba(110, 168, 254, 0.28);
      }

      .form-status {
        margin: 18px 0 0;
        color: #b9c7e6;
        font-size: 0.95rem;
        min-height: 1.4em;
      }

      @media (max-width: 640px) {
        body {
          padding: 14px;
        }

        .support-card__header,
        .support-card__body {
          padding-left: 20px;
          padding-right: 20px;
        }

        .form-actions {
          justify-content: stretch;
        }

        button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <main id="app"></main>

    <script>
      function createField({ id, label, type, required, autocomplete, placeholder, helperText }) {
        const describedBy = [
          helperText ? `${id}-help` : null,
          `${id}-error`,
        ].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${id}">
              ${label}${required ? ' <span class="required-mark" aria-hidden="true">*</span>' : ''}
            </label>
            <input
              id="${id}"
              name="${id}"
              type="${type}"
              ${required ? 'required' : ''}
              autocomplete="${autocomplete}"
              placeholder="${placeholder}"
              aria-describedby="${describedBy}"
            />
            ${helperText ? `<p class="helper-text" id="${id}-help">${helperText}</p>` : ''}
            <p class="error-text" id="${id}-error" role="alert" aria-live="assertive" hidden></p>
          </div>
        `;
      }

      function App() {
        return `
          <section class="support-card" aria-labelledby="support-title">
            <header class="support-card__header">
              <p class="eyebrow">Support</p>
              <h1 id="support-title">Contact our team</h1>
            </header>
            <div class="support-card__body">
              <p class="support-copy">
                Send us a message and we’ll get back to you as soon as possible.
              </p>
              <form id="support-form" novalidate>
                ${createField({
                  id: "full-name",
                  label: "Full name",
                  type: "text",
                  required: true,
                  autocomplete: "name",
                  placeholder: "Jane Doe",
                })}
                ${createField({
                  id: "email-address",
                  label: "Email address",
                  type: "email",
                  required: true,
                  autocomplete: "email",
                  placeholder: "jane@example.com",
                })}
                ${createField({
                  id: "phone-number",
                  label: "Phone number",
                  type: "tel",
                  required: false,
                  autocomplete: "tel",
                  placeholder: "+1 555 123 4567",
                  helperText: "Optional. Include country code if needed, for example +1 555 123 4567.",
                })}
                <div class="form-actions">
                  <button type="submit">Submit request</button>
                </div>
              </form>
              <p class="form-status" id="form-status" aria-live="polite"></p>
            </div>
          </section>
        `;
      }

      function setError(fieldId, message) {
        const errorEl = document.getElementById(fieldId + "-error");
        errorEl.textContent = message;
        errorEl.hidden = !message;
      }

      function validateForm(form) {
        const fullName = form.elements["full-name"];
        const emailAddress = form.elements["email-address"];
        const phoneNumber = form.elements["phone-number"];

        let valid = true;

        if (!fullName.value.trim()) {
          setError("full-name", "Full name is required.");
          valid = false;
        } else {
          setError("full-name", "");
        }

        if (!emailAddress.value.trim()) {
          setError("email-address", "Email address is required.");
          valid = false;
        } else if (!emailAddress.validity.valid) {
          setError("email-address", "Enter a valid email address.");
          valid = false;
        } else {
          setError("email-address", "");
        }

        if (phoneNumber.value.trim()) {
          setError("phone-number", "");
        } else {
          setError("phone-number", "");
        }

        return valid;
      }

      function init() {
        const app = document.getElementById("app");
        app.innerHTML = App();

        const form = document.getElementById("support-form");
        const status = document.getElementById("form-status");
        const fields = ["full-name", "email-address", "phone-number"];

        fields.forEach((fieldId) => {
          const input = document.getElementById(fieldId);
          input.addEventListener("input", () => {
            if (fieldId === "phone-number") {
              return;
            }
            if (fieldId === "email-address" && input.value.trim() && input.validity.valid) {
              setError(fieldId, "");
              return;
            }
            if (input.value.trim()) {
              setError(fieldId, "");
            }
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          status.textContent = "";

          if (!validateForm(form)) {
            status.textContent = "Please correct the highlighted fields.";
            return;
          }

          status.textContent = "Your request is ready to send.";
          form.reset();
          fields.forEach((fieldId) => setError(fieldId, ""));
        });
      }

      init();
    </script>
  </body>
</html>
